-- =============================================================================
-- Verification for the ONISEP Silver tables (career_intelligence.silver.onisep_*).
-- Partly GENERATED (empty strings, lineage, licence). Every check_* must be TRUE.
-- Expected values recalculated from Bronze on 2026-11-09 (snapshot 20261109).
-- =============================================================================

-- 1. Row counts: entities = Bronze rows; relationships = number of nested items in Bronze
SELECT
  (SELECT count(*) FROM career_intelligence.silver.onisep_metier)             = (SELECT count(*) FROM career_intelligence.bronze.onisep_fiches_metiers)       AS check_rows_metier,
  (SELECT count(*) FROM career_intelligence.silver.onisep_formation)          = (SELECT count(*) FROM career_intelligence.bronze.onisep_fiches_formations)    AS check_rows_formation,
  (SELECT count(*) FROM career_intelligence.silver.onisep_formation_initiale) = (SELECT count(*) FROM career_intelligence.bronze.onisep_formations_initiales) AS check_rows_formation_initiale,
  (SELECT count(*) FROM career_intelligence.silver.onisep_metier_rome)
    = (SELECT sum(size(xpath(romesV3, '/romesV3/romeV3/text()'))) FROM career_intelligence.bronze.onisep_fiches_metiers)              AS check_rows_metier_rome,
  (SELECT count(*) FROM career_intelligence.silver.onisep_formation_metier)
    = (SELECT sum(size(xpath(metiers_formation, '/metiers_formation/metier/id/text()'))) FROM career_intelligence.bronze.onisep_fiches_formations) AS check_rows_formation_metier,
  (SELECT count(*) FROM career_intelligence.silver.onisep_metier_formation_min_requise)
    = (SELECT sum(size(xpath(formations_min_requise, '/formations_min_requise/formation_min_requise/id/text()'))) FROM career_intelligence.bronze.onisep_fiches_metiers) AS check_rows_min_requise,
  (SELECT count(*) FROM career_intelligence.silver.onisep_metier_associe)
    = (SELECT sum(size(xpath(metiers_associes, '/metiers_associes/metier_associe/id/text()'))) FROM career_intelligence.bronze.onisep_fiches_metiers) AS check_rows_metier_associe,
  (SELECT count(*) FROM career_intelligence.silver.onisep_formation_poursuite)
    = (SELECT sum(size(xpath(poursuites_etudes, '/poursuites_etudes/poursuite_etudes/formation_poursuite_Etudes/@id'))) FROM career_intelligence.bronze.onisep_fiches_formations) AS check_rows_poursuite;
-- Expected (20261109): 1138 | 2349 | 5799 | 976 | 6756 | 7184 | 825 | 2664

-- 2. Primary keys: unique and non-null
SELECT
  (SELECT count(*) = count(DISTINCT identifiant) AND count_if(identifiant IS NULL) = 0 FROM career_intelligence.silver.onisep_metier)             AS check_pk_metier,
  (SELECT count(*) = count(DISTINCT identifiant) AND count_if(identifiant IS NULL) = 0 FROM career_intelligence.silver.onisep_formation)          AS check_pk_formation,
  (SELECT count(*) = count(DISTINCT identifiant) AND count_if(identifiant IS NULL OR identifiant = '') = 0
     FROM career_intelligence.silver.onisep_formation_initiale)                                                                                      AS check_pk_formation_initiale,
  (SELECT count(*) = count(DISTINCT identifiant_metier, code_rome_source)
          AND count_if(identifiant_metier IS NULL OR code_rome_source IS NULL) = 0 FROM career_intelligence.silver.onisep_metier_rome)              AS check_pk_metier_rome,
  (SELECT count(*) = count(DISTINCT identifiant_formation, identifiant_metier)
          AND count_if(identifiant_formation IS NULL OR identifiant_metier IS NULL) = 0 FROM career_intelligence.silver.onisep_formation_metier)   AS check_pk_formation_metier,
  (SELECT count(*) = count(DISTINCT identifiant_metier, identifiant_formation)
          AND count_if(identifiant_metier IS NULL OR identifiant_formation IS NULL) = 0
     FROM career_intelligence.silver.onisep_metier_formation_min_requise)                                                                             AS check_pk_min_requise,
  (SELECT count(*) = count(DISTINCT identifiant_metier, identifiant_metier_associe)
          AND count_if(identifiant_metier IS NULL OR identifiant_metier_associe IS NULL) = 0 FROM career_intelligence.silver.onisep_metier_associe) AS check_pk_metier_associe,
  (SELECT count(*) = count(DISTINCT identifiant_formation, identifiant_formation_poursuite)
          AND count_if(identifiant_formation IS NULL OR identifiant_formation_poursuite IS NULL) = 0
     FROM career_intelligence.silver.onisep_formation_poursuite)                                                                                      AS check_pk_poursuite;

-- 3. Source identifiers preserved: same identifier sets as Bronze (both directions)
SELECT
  (SELECT count(*) FROM career_intelligence.bronze.onisep_fiches_metiers b FULL JOIN career_intelligence.silver.onisep_metier s USING (identifiant)
     WHERE b._source_row IS NULL OR s._source_row IS NULL OR b._source_row <> s._source_row) = 0          AS check_ids_metier,
  (SELECT count(*) FROM career_intelligence.bronze.onisep_fiches_formations b FULL JOIN career_intelligence.silver.onisep_formation s USING (identifiant)
     WHERE b._source_row IS NULL OR s._source_row IS NULL OR b._source_row <> s._source_row) = 0          AS check_ids_formation,
  (SELECT count(*) FROM (SELECT regexp_extract(url_et_id_onisep, 'FOR\\.[0-9]+', 0) AS identifiant, url_et_id_onisep, _source_row FROM career_intelligence.bronze.onisep_formations_initiales) b
     FULL JOIN career_intelligence.silver.onisep_formation_initiale s USING (identifiant)
     WHERE b._source_row IS NULL OR s._source_row IS NULL OR b._source_row <> s._source_row
        OR b.url_et_id_onisep <> s.url_onisep) = 0                                                         AS check_ids_formation_initiale;

-- 4. Foreign keys between ONISEP entities (must resolve)
SELECT
  (SELECT count(*) FROM career_intelligence.silver.onisep_formation f LEFT ANTI JOIN career_intelligence.silver.onisep_formation_initiale i USING (identifiant)) = 0  AS check_fk_formation_in_catalogue,
  (SELECT count(*) FROM career_intelligence.silver.onisep_formation_metier r LEFT ANTI JOIN career_intelligence.silver.onisep_metier m ON m.identifiant = r.identifiant_metier) = 0 AS check_fk_formation_metier_metier,
  (SELECT count(*) FROM career_intelligence.silver.onisep_formation_metier r LEFT ANTI JOIN career_intelligence.silver.onisep_formation f ON f.identifiant = r.identifiant_formation) = 0 AS check_fk_formation_metier_formation,
  (SELECT count(DISTINCT identifiant_metier) FROM career_intelligence.silver.onisep_formation_metier) = 984                                       AS check_formation_metier_984,
  (SELECT count(*) FROM career_intelligence.silver.onisep_formation f WHERE NOT EXISTS
     (SELECT 1 FROM career_intelligence.silver.onisep_formation_metier r WHERE r.identifiant_formation = f.identifiant)) = 0                     AS check_every_fiche_has_metier,
  (SELECT count(*) FROM career_intelligence.silver.onisep_metier_rome r LEFT ANTI JOIN career_intelligence.silver.onisep_metier m ON m.identifiant = r.identifiant_metier) = 0 AS check_fk_metier_rome_metier,
  (SELECT count(*) FROM career_intelligence.silver.onisep_metier_formation_min_requise r LEFT ANTI JOIN career_intelligence.silver.onisep_metier m ON m.identifiant = r.identifiant_metier) = 0 AS check_fk_min_requise_metier,
  (SELECT count(*) FROM career_intelligence.silver.onisep_metier_associe r LEFT ANTI JOIN career_intelligence.silver.onisep_metier m ON m.identifiant = r.identifiant_metier) = 0 AS check_fk_associe_metier,
  (SELECT count(*) FROM career_intelligence.silver.onisep_formation_poursuite r LEFT ANTI JOIN career_intelligence.silver.onisep_formation f ON f.identifiant = r.identifiant_formation) = 0 AS check_fk_poursuite_formation;

-- 5. ROME references: valid codes resolve, unresolved codes are kept and quantified
SELECT
  count(*)                                                     AS links,
  count_if(statut_code = 'valide')                             AS valid_links,
  count_if(statut_code = 'non_resolu')                         AS unresolved_links,
  count(DISTINCT CASE WHEN statut_code = 'non_resolu' THEN code_rome_source END) AS unresolved_distinct_codes,
  concat_ws(', ', sort_array(collect_set(CASE WHEN statut_code = 'non_resolu' THEN code_rome_source END))) AS unresolved_codes,
  count_if(statut_code = 'valide' AND code_rome IS NULL)
    + count_if(statut_code = 'non_resolu' AND code_rome IS NOT NULL)
    + count_if(code_rome IS NOT NULL AND code_rome <> code_rome_source) = 0                          AS check_status_consistent,
  (SELECT count(*) FROM career_intelligence.silver.onisep_metier_rome r LEFT ANTI JOIN career_intelligence.silver.rome_metier m ON m.code_rome = r.code_rome
     WHERE r.code_rome IS NOT NULL) = 0                                                               AS check_valid_codes_in_rome
FROM career_intelligence.silver.onisep_metier_rome;
-- Expected (20261109): 976 links | 968 valid | 8 unresolved | 6 codes: A15, B16, H2, K15, K19, N2

WITH p AS (
  SELECT m.identifiant, count(r.code_rome_source) AS n_codes, count_if(r.statut_code = 'valide') AS n_valid
  FROM career_intelligence.silver.onisep_metier m LEFT JOIN career_intelligence.silver.onisep_metier_rome r ON r.identifiant_metier = m.identifiant
  GROUP BY m.identifiant)
SELECT count(*) AS metiers, count_if(n_codes > 0) AS with_any_code, count_if(n_valid > 0) AS with_valid_code,
       count_if(n_codes > 0 AND n_valid = 0) AS only_unresolved, count_if(n_valid > 0 AND n_codes > n_valid) AS mixed,
       count_if(n_codes = 0) AS without_code,
       count(*) = 1138 AND count_if(n_codes > 0) = 931 AND count_if(n_valid > 0) = 928 AS check_rome_coverage
FROM p;

-- 6. Other references: unresolved targets are kept, flagged and quantified (not enforced)
SELECT
  (SELECT count_if(NOT formation_dans_catalogue) FROM career_intelligence.silver.onisep_metier_formation_min_requise)                AS min_requise_outside_catalogue,
  (SELECT count_if(NOT metier_associe_connu) FROM career_intelligence.silver.onisep_metier_associe)                                 AS associe_unknown_metier,
  (SELECT count_if(NOT formation_dans_catalogue) FROM career_intelligence.silver.onisep_formation_poursuite)                        AS poursuite_outside_catalogue,
  (SELECT count_if(formation_dans_catalogue <> (i.identifiant IS NOT NULL)) FROM career_intelligence.silver.onisep_metier_formation_min_requise r
     LEFT JOIN career_intelligence.silver.onisep_formation_initiale i ON i.identifiant = r.identifiant_formation) = 0
  AND (SELECT count_if(metier_associe_connu <> (m.identifiant IS NOT NULL)) FROM career_intelligence.silver.onisep_metier_associe r
     LEFT JOIN career_intelligence.silver.onisep_metier m ON m.identifiant = r.identifiant_metier_associe) = 0
  AND (SELECT count_if(formation_dans_catalogue <> (i.identifiant IS NOT NULL)) FROM career_intelligence.silver.onisep_formation_poursuite r
     LEFT JOIN career_intelligence.silver.onisep_formation_initiale i ON i.identifiant = r.identifiant_formation_poursuite) = 0      AS check_flags_consistent;
-- Expected (20261109): 58 | 200 | 1

-- 7. Normalised text: no empty strings, no edge whitespace; labels without double spaces,
--    tabs or non-breaking spaces (HTML descriptions keep their internal typography)
SELECT sum(empty_strings) AS empty_strings, sum(edge_whitespace) AS edge_whitespace, sum(label_ws_issues) AS label_ws_issues,
       sum(empty_strings) + sum(edge_whitespace) + sum(label_ws_issues) = 0 AS check_normalised_text
FROM (
  SELECT 'onisep_formation' AS t, count_if(identifiant = '' OR code_scolarite = '' OR libelle_complet = '' OR sigle = '' OR libelle_generique = '' OR libelle_specifique = '' OR type_option = '' OR type_formation_sigle = '' OR type_formation_libelle_court = '' OR type_formation_libelle = '' OR duree_formation = '' OR niveau_certification = '' OR niv_code = '' OR niveau_etudes_id = '' OR niveau_etudes_libelle = '' OR nsf_discipline_code = '' OR nsf_discipline_libelle = '' OR nsf_fonction_code = '' OR nsf_fonction_libelle = '' OR sous_tutelle = '' OR url = '' OR descriptif_format_court = '' OR descriptif_acces = '' OR attendus = '' OR descriptif_poursuite_etudes = '' OR annee_premiere_session = '' OR annee_derniere_session = '') AS empty_strings, count_if(identifiant RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR code_scolarite RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR libelle_complet RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR sigle RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR libelle_generique RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR libelle_specifique RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR type_option RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR type_formation_sigle RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR type_formation_libelle_court RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR type_formation_libelle RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR duree_formation RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR niveau_certification RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR niv_code RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR niveau_etudes_id RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR niveau_etudes_libelle RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR nsf_discipline_code RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR nsf_discipline_libelle RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR nsf_fonction_code RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR nsf_fonction_libelle RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR sous_tutelle RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR url RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR descriptif_format_court RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR descriptif_acces RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR attendus RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR descriptif_poursuite_etudes RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR annee_premiere_session RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR annee_derniere_session RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$') AS edge_whitespace, count_if(identifiant RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR code_scolarite RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR libelle_complet RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR sigle RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR libelle_generique RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR libelle_specifique RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR type_option RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR type_formation_sigle RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR type_formation_libelle_court RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR type_formation_libelle RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR duree_formation RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR niveau_certification RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR niv_code RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR niveau_etudes_id RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR niveau_etudes_libelle RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR nsf_discipline_code RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR nsf_discipline_libelle RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR nsf_fonction_code RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR nsf_fonction_libelle RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR sous_tutelle RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR url RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR annee_premiere_session RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR annee_derniere_session RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]') AS label_ws_issues FROM career_intelligence.silver.onisep_formation
  UNION ALL SELECT 'onisep_formation_initiale' AS t, count_if(identifiant = '' OR url_onisep = '' OR libelle_formation_principal = '' OR sigle_formation = '' OR sigle_type_formation = '' OR libelle_type_formation = '' OR code_scolarite = '' OR code_rncp = '' OR duree = '' OR niveau_de_sortie_indicatif = '' OR niveau_de_certification = '' OR libelle_niveau_de_certification = '' OR tutelle = '') AS empty_strings, count_if(identifiant RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR url_onisep RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR libelle_formation_principal RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR sigle_formation RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR sigle_type_formation RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR libelle_type_formation RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR code_scolarite RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR code_rncp RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR duree RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR niveau_de_sortie_indicatif RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR niveau_de_certification RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR libelle_niveau_de_certification RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR tutelle RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$') AS edge_whitespace, count_if(identifiant RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR url_onisep RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR libelle_formation_principal RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR sigle_formation RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR sigle_type_formation RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR libelle_type_formation RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR code_scolarite RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR code_rncp RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR duree RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR niveau_de_sortie_indicatif RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR niveau_de_certification RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR libelle_niveau_de_certification RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR tutelle RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]') AS label_ws_issues FROM career_intelligence.silver.onisep_formation_initiale
  UNION ALL SELECT 'onisep_formation_metier' AS t, count_if(identifiant_formation = '' OR identifiant_metier = '') AS empty_strings, count_if(identifiant_formation RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR identifiant_metier RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$') AS edge_whitespace, count_if(identifiant_formation RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR identifiant_metier RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]') AS label_ws_issues FROM career_intelligence.silver.onisep_formation_metier
  UNION ALL SELECT 'onisep_formation_poursuite' AS t, count_if(identifiant_formation = '' OR identifiant_formation_poursuite = '' OR libelle_formation_poursuite = '') AS empty_strings, count_if(identifiant_formation RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR identifiant_formation_poursuite RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR libelle_formation_poursuite RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$') AS edge_whitespace, count_if(identifiant_formation RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR identifiant_formation_poursuite RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR libelle_formation_poursuite RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]') AS label_ws_issues FROM career_intelligence.silver.onisep_formation_poursuite
  UNION ALL SELECT 'onisep_metier' AS t, count_if(identifiant = '' OR nom_metier = '' OR libelle_feminin = '' OR libelle_masculin = '' OR accroche_metier = '' OR format_court = '' OR competences = '' OR condition_travail = '' OR nature_travail = '' OR acces_metier = '' OR vie_professionnelle = '' OR niveau_acces_min_id = '' OR niveau_acces_min_libelle = '' OR metier_transverse = '') AS empty_strings, count_if(identifiant RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR nom_metier RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR libelle_feminin RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR libelle_masculin RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR accroche_metier RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR format_court RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR competences RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR condition_travail RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR nature_travail RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR acces_metier RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR vie_professionnelle RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR niveau_acces_min_id RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR niveau_acces_min_libelle RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR metier_transverse RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$') AS edge_whitespace, count_if(identifiant RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR nom_metier RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR libelle_feminin RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR libelle_masculin RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR niveau_acces_min_id RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR niveau_acces_min_libelle RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR metier_transverse RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]') AS label_ws_issues FROM career_intelligence.silver.onisep_metier
  UNION ALL SELECT 'onisep_metier_associe' AS t, count_if(identifiant_metier = '' OR identifiant_metier_associe = '' OR libelle_metier_associe = '') AS empty_strings, count_if(identifiant_metier RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR identifiant_metier_associe RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR libelle_metier_associe RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$') AS edge_whitespace, count_if(identifiant_metier RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR identifiant_metier_associe RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR libelle_metier_associe RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]') AS label_ws_issues FROM career_intelligence.silver.onisep_metier_associe
  UNION ALL SELECT 'onisep_metier_formation_min_requise' AS t, count_if(identifiant_metier = '' OR identifiant_formation = '' OR libelle_formation = '') AS empty_strings, count_if(identifiant_metier RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR identifiant_formation RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR libelle_formation RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$') AS edge_whitespace, count_if(identifiant_metier RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR identifiant_formation RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR libelle_formation RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]') AS label_ws_issues FROM career_intelligence.silver.onisep_metier_formation_min_requise
  UNION ALL SELECT 'onisep_metier_rome' AS t, count_if(identifiant_metier = '' OR code_rome_source = '' OR code_rome = '' OR statut_code = '') AS empty_strings, count_if(identifiant_metier RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR code_rome_source RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR code_rome RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$' OR statut_code RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$') AS edge_whitespace, count_if(identifiant_metier RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR code_rome_source RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR code_rome RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]' OR statut_code RLIKE '[\\s\\x{00A0}\\x{202F}]{2,}|[\\t\\x{00A0}\\x{202F}]') AS label_ws_issues FROM career_intelligence.silver.onisep_metier_rome
);

SELECT
  (SELECT count_if(exists(synonymes, s -> s.nom_metier RLIKE '^[\\s\\x{00A0}\\x{202F}]|[\\s\\x{00A0}\\x{202F}]$|[\\s\\x{00A0}\\x{202F}]{2,}|\\x{00A0}'))
     FROM career_intelligence.silver.onisep_metier) = 0                                                         AS check_array_labels_normalised,
  (SELECT count_if(duree_formation LIKE '%"%') FROM career_intelligence.silver.onisep_formation) = 0           AS check_duree_unquoted,
  (SELECT count_if(creation_date IS NULL OR modification_date IS NULL) FROM career_intelligence.silver.onisep_formation) = 0
    AND (SELECT count_if(date_creation IS NULL OR date_de_modification IS NULL) FROM career_intelligence.silver.onisep_formation_initiale) = 0 AS check_dates_parsed,
  (SELECT count_if(exists(codes_nsf, c -> NOT c RLIKE '^[0-9]+$')) FROM career_intelligence.silver.onisep_formation_initiale) = 0 AS check_codes_nsf_numeric;

-- 8. Lineage complete: 10 lineage columns non-null, one source checksum per table
SELECT count(*) AS tables, sum(incomplete) AS incomplete_rows, max(shas) AS max_checksums_per_table,
       sum(incomplete) = 0 AND max(shas) = 1 AS check_lineage
FROM (
  SELECT 'onisep_metier' AS t, count(*) AS n, count_if(_source_name IS NULL OR _source_resource IS NULL OR _dataset IS NULL OR _source_url IS NULL OR _source_file IS NULL OR _source_sha256 IS NULL OR _snapshot IS NULL OR _run_id IS NULL OR _source_row IS NULL OR _ingested_at IS NULL) AS incomplete, count(DISTINCT _source_sha256) AS shas FROM career_intelligence.silver.onisep_metier
  UNION ALL SELECT 'onisep_formation' AS t, count(*) AS n, count_if(_source_name IS NULL OR _source_resource IS NULL OR _dataset IS NULL OR _source_url IS NULL OR _source_file IS NULL OR _source_sha256 IS NULL OR _snapshot IS NULL OR _run_id IS NULL OR _source_row IS NULL OR _ingested_at IS NULL) AS incomplete, count(DISTINCT _source_sha256) AS shas FROM career_intelligence.silver.onisep_formation
  UNION ALL SELECT 'onisep_formation_initiale' AS t, count(*) AS n, count_if(_source_name IS NULL OR _source_resource IS NULL OR _dataset IS NULL OR _source_url IS NULL OR _source_file IS NULL OR _source_sha256 IS NULL OR _snapshot IS NULL OR _run_id IS NULL OR _source_row IS NULL OR _ingested_at IS NULL) AS incomplete, count(DISTINCT _source_sha256) AS shas FROM career_intelligence.silver.onisep_formation_initiale
  UNION ALL SELECT 'onisep_metier_rome' AS t, count(*) AS n, count_if(_source_name IS NULL OR _source_resource IS NULL OR _dataset IS NULL OR _source_url IS NULL OR _source_file IS NULL OR _source_sha256 IS NULL OR _snapshot IS NULL OR _run_id IS NULL OR _source_row IS NULL OR _ingested_at IS NULL) AS incomplete, count(DISTINCT _source_sha256) AS shas FROM career_intelligence.silver.onisep_metier_rome
  UNION ALL SELECT 'onisep_formation_metier' AS t, count(*) AS n, count_if(_source_name IS NULL OR _source_resource IS NULL OR _dataset IS NULL OR _source_url IS NULL OR _source_file IS NULL OR _source_sha256 IS NULL OR _snapshot IS NULL OR _run_id IS NULL OR _source_row IS NULL OR _ingested_at IS NULL) AS incomplete, count(DISTINCT _source_sha256) AS shas FROM career_intelligence.silver.onisep_formation_metier
  UNION ALL SELECT 'onisep_metier_formation_min_requise' AS t, count(*) AS n, count_if(_source_name IS NULL OR _source_resource IS NULL OR _dataset IS NULL OR _source_url IS NULL OR _source_file IS NULL OR _source_sha256 IS NULL OR _snapshot IS NULL OR _run_id IS NULL OR _source_row IS NULL OR _ingested_at IS NULL) AS incomplete, count(DISTINCT _source_sha256) AS shas FROM career_intelligence.silver.onisep_metier_formation_min_requise
  UNION ALL SELECT 'onisep_metier_associe' AS t, count(*) AS n, count_if(_source_name IS NULL OR _source_resource IS NULL OR _dataset IS NULL OR _source_url IS NULL OR _source_file IS NULL OR _source_sha256 IS NULL OR _snapshot IS NULL OR _run_id IS NULL OR _source_row IS NULL OR _ingested_at IS NULL) AS incomplete, count(DISTINCT _source_sha256) AS shas FROM career_intelligence.silver.onisep_metier_associe
  UNION ALL SELECT 'onisep_formation_poursuite' AS t, count(*) AS n, count_if(_source_name IS NULL OR _source_resource IS NULL OR _dataset IS NULL OR _source_url IS NULL OR _source_file IS NULL OR _source_sha256 IS NULL OR _snapshot IS NULL OR _run_id IS NULL OR _source_row IS NULL OR _ingested_at IS NULL) AS incomplete, count(DISTINCT _source_sha256) AS shas FROM career_intelligence.silver.onisep_formation_poursuite
);

